263	bool OpenAIResponsesAgent::start(const AgentRequest& request)
264	{
265	    if (!ready() || m_busy)
266	        return false;
267	    m_input_history = json::array();
268	    m_pending_call_id.clear();
269	    m_waiting_for_tool = false;
270	    m_request_id = request.request_id;
271	    m_request_sequence = 0;
272	    m_rejected_calls = 0;
273	    m_title_request = request.purpose == AgentRequest::Purpose::ConversationTitle;
274	    m_session       = request.session;
275	    m_allow_import = std::any_of(request.attachments.begin(), request.attachments.end(),
276	                                 [](const AgentAttachmentContext& attachment) { return attachment.importable; });
277	    return post(initial_input(request));
278	}
