286	    // A function result is text only; the picture follows it as an image input.
287	    if (result.image)
288	        input.push_back(json{{"role", "user"},
289	                             {"content", json::array({json{{"type", "input_text"}, {"text", "The image returned by call " + result.call_id + "."}},

