76	const std::vector<DeferredToolset>& deferred_toolsets()
77	{
78	    // The guide's toolsets, with four frequent reads left eager. Empty future
79	    // toolsets (machine and calibration) are not advertised.
80	    static const std::vector<DeferredToolset> sets{
81	        {"core", "Analyze object geometry, preview and apply settings, record print intent and plans, start slicing, and read slice reports.",
82	         {ToolHandler::ObjectAnalyze, ToolHandler::SettingsPreviewPatch, ToolHandler::SettingsApplyPatch,
83	          ToolHandler::IntentUpdate, ToolHandler::PlanSet, ToolHandler::SliceStart, ToolHandler::SliceReportRead}},
84	        {"project", "Open or create a project and read its attachments.",
85	         {ToolHandler::ProjectOpen, ToolHandler::AttachmentRead}},
86	        {"setup", "Find presets and printers, preview and change the project's printer and filament setup.",
87	         {ToolHandler::PresetsList, ToolHandler::PrinterList, ToolHandler::PrinterSetupPreview, ToolHandler::PrinterSetup}},
88	        {"geometry", "Place objects, arrange plates, import attached models, and delete project items.",
89	         {ToolHandler::ObjectPlace, ToolHandler::PlateLayout, ToolHandler::ObjectImport, ToolHandler::ProjectDeleteItems}},
90	        {"reshape", "Preview cuts, cut or split objects, merge objects, and repair meshes.",
91	         {ToolHandler::ObjectDividePreview, ToolHandler::ObjectDivide, ToolHandler::ObjectMerge, ToolHandler::ObjectRepair}},
92	        {"regions", "Annotate local object regions with printing requirements such as support, strength or surface finish.",
93	         {ToolHandler::RegionAnnotate}},
94	        {"check", "Render a view, inspect sliced layers or G-code, and cancel an activity.",
95	         {ToolHandler::ViewRender, ToolHandler::SliceInspect, ToolHandler::ActivityCancel}},
96	        {"output", "Export G-code, sliced or project 3MF, STL, or preset bundles to a file.",
97	         {ToolHandler::ExportFile}}
98	    };
99	    return sets;
100	}
