102	const DeferredToolset* deferred_toolset(ToolHandler handler)
103	{
104	    for (const auto& set : deferred_toolsets())
105	        if (std::find(set.handlers.begin(), set.handlers.end(), handler) != set.handlers.end())
106	            return &set;
107	    return nullptr;
108	}
