// What one turn said and did, from the host's own records.
nlohmann::json journey_turn(const nlohmann::json& said, std::size_t messages, std::size_t calls, std::size_t requests) const
{
    const Agent::AgentHost& host = installed_shell()->agent_pane()->web_view().host();
    nlohmann::json replies = nlohmann::json::array();
    const auto     conversation = host.conversation();
    for (std::size_t i = messages; i < conversation.size(); ++i) {
        const Agent::ConversationMessage& message = conversation[i];
        if (message.role != Agent::MessageRole::Assistant)
            continue;
        const char* state = message.state == Agent::MessageState::Complete ? "complete" :
                            message.state == Agent::MessageState::Failed   ? "failed" :
                            message.state == Agent::MessageState::Stopped  ? "stopped" : "streaming";
        nlohmann::json reply{{"text", message.text}, {"state", state}};
        if (message.error)
            reply["error"] = message.error->code;
        replies.push_back(std::move(reply));
    }
    nlohmann::json made = nlohmann::json::array();
    const auto&    activities = host.tools().activities();
    for (std::size_t i = calls; i < activities.size(); ++i) {
        const Agent::ToolActivity& activity = activities[i];
        nlohmann::json call{{"tool", activity.tool},
                            {"arguments", nlohmann::json::parse(activity.arguments_json, nullptr, false)},
                            {"state", Agent::tool_state_name(activity.state)},
                            {"changesProject", activity.action_class != Agent::ActionClass::ReadOnly}};
        if (activity.error)
            call["error"] = {{"code", activity.error->code}, {"message", activity.error->message}};
        // A slice report or a settings page is large; the review needs
        // what came back, not all of it.
        constexpr std::size_t kResultLimit = 6000;
        call["resultBytes"] = activity.result_json.size();
        if (activity.result_json.size() <= kResultLimit)
            call["result"] = nlohmann::json::parse(activity.result_json, nullptr, false);
        else
            call["resultStart"] = activity.result_json.substr(0, kResultLimit);
        call["image"] = activity.image != nullptr;
        made.push_back(std::move(call));
    }
    nlohmann::json usage = nlohmann::json::array();
    for (std::size_t i = requests; i < g_journey_usage.size(); ++i)
        usage.push_back(g_journey_usage[i]);
    return {{"said", said}, {"replies", std::move(replies)}, {"calls", std::move(made)}, {"requests", std::move(usage)}};
}

void journey_finish(const std::string& stopped)
{
    Agent::AgentHost& host     = installed_shell()->agent_pane()->web_view().host();
    const auto        snapshot = installed_shell()->workspace()->snapshot();
    nlohmann::json changed = nlohmann::json::array();
    for (const Workspace::PresetDelta& delta : snapshot.preset_deltas)
        changed.push_back({{"key", delta.key}, {"presetType", delta.preset_type}, {"preset", delta.preset}, {"value", delta.value}});
    nlohmann::json project{{"printerPreset", snapshot.setup.printer_preset},
                           {"filamentPreset", snapshot.setup.filament_preset},
                           {"processPreset", snapshot.setup.process_preset},
                           {"changedSettings", std::move(changed)}};
    // The rest as the model itself could read it. A request cap leaves a
    // turn running, and the coordinator would queue this read behind it.
    if (stopped != "request_cap") {
        const auto id = host.tools().propose({"workspace_inspect",
                                              R"({"sections":["summary","objects","intent","plan","slicing","printer"]})"},
                                             "journey-end").action_id;
        host.pump_tools();
        const Agent::ToolActivity* inspected = host.tools().find(id);
        check(inspected != nullptr && inspected->state == Agent::ToolState::Succeeded, "journey_end_state_read");
        if (inspected != nullptr && inspected->state == Agent::ToolState::Succeeded)
            project["workspace"] = nlohmann::json::parse(inspected->result_json, nullptr, false);
    }
    std::uint64_t input = 0, cached = 0, output = 0;
    for (const auto& request : g_journey_usage) {
        input  += request.value("inputTokens", std::uint64_t{0});
        cached += request.value("cachedInputTokens", std::uint64_t{0});
        output += request.value("outputTokens", std::uint64_t{0});
    }
    const nlohmann::json result{{"scenario", m_journey.value("name", m_state->journey_scenario.stem().string())},
                                {"route", g_journey_route},
                                {"stopped", stopped},
                                {"turns", m_journey_turns},
                                {"refusedCalls", g_journey_refusals},
                                {"project", std::move(project)},
                                {"usage", {{"requests", g_journey_usage.size()}, {"inputTokens", input},
                                           {"cachedInputTokens", cached}, {"outputTokens", output}}}};
    std::ofstream out(m_state->journey_output.string(), std::ios::binary);
    out << result.dump(2, ' ', false, nlohmann::json::error_handler_t::replace) << '\n';
    check(out.good(), "journey_recorded");
    std::cerr << "HARNESS JOURNEY stopped=" << stopped << " requests=" << g_journey_usage.size() << " input_tokens=" << input
              << " cached_input_tokens=" << cached << " output_tokens=" << output << '\n';
    finish();
}

