// One line of outcome facts per record, for both arms.
import fs from 'node:fs';
import path from 'node:path';
const root = process.argv[2];
const total = {};
for (const arm of ['base', 'new']) {
  const dir = path.join(root, arm);
  if (!fs.existsSync(dir)) continue;
  total[arm] = { runs: 0, requests: 0, input: 0, cached: 0, output: 0 };
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
    let r;
    try { r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')); }
    catch (error) { console.log(`${arm} ${file}: unreadable (${error.message.slice(0, 60)})`); continue; }
    const t = total[arm];
    t.runs++; t.requests += r.usage.requests; t.input += r.usage.inputTokens; t.cached += r.usage.cachedInputTokens; t.output += r.usage.outputTokens;
    const turns = r.turns.map((turn, index) => {
      const calls = turn.calls.map(c => c.tool);
      const intents = turn.calls.filter(c => c.tool === 'intent_update' && c.state === 'succeeded').map(c =>
        `"${c.arguments.setupTitle ?? ''}" [` + (c.arguments.fields ?? []).map(f => `${f.field}=${f.value ?? '?' + (f.question ?? '')}${f.assumed ? '(assumed)' : ''}`).join('; ') + ']');
      const settingsForPresets = turn.calls.filter(c => c.tool === 'settings_search' && /petg|pla|preset/i.test(c.arguments?.query ?? '')).length;
      const firstPresets = calls.indexOf('presets_list');
      return `  t${index}${turn.said === null ? '(open)' : ''}: calls=${calls.length} [${[...new Set(calls)].join(',')}]` +
        (intents.length ? `\n      intent: ${intents.join(' | ')}` : '') +
        (settingsForPresets ? `\n      settings_search used to look for a material/preset: ${settingsForPresets}` : '') +
        (firstPresets >= 0 ? `\n      presets_list first at call ${firstPresets + 1}` : '') +
        (calls.includes('object_analyze') ? `\n      object_analyze: yes` : '') +
        (calls.includes('view_render') ? `\n      view_render: yes` : '') +
        (turn.replies.some(m => m.state !== 'complete') ? `\n      reply: ${turn.replies.filter(m => m.state !== 'complete').map(m => m.state + ' ' + (m.error ?? '')).join(',')}` : '');
    });
    const p = r.project, w = p.workspace ?? {};
    console.log(`${arm} ${file.replace('.json', '')}: ${r.stopped} requests=${r.usage.requests} in=${r.usage.inputTokens} refused=${r.refusedCalls.length}${r.refusedCalls.length ? ' (' + r.refusedCalls.map(c => c.tool).join(',') + ')' : ''}`);
    console.log(turns.join('\n'));
    console.log(`  end: filament=${p.filamentPreset} | process=${p.processPreset} | changed=${p.changedSettings.map(c => c.key + '=' + c.value).join(',') || 'none'} | sliced=${(w.slicing?.plates ?? []).map(x => x.sliced).join(',')}`);
    console.log(`  end intent: ${(w.intent?.fields ?? []).map(f => `${f.field}=${f.value}(${f.provenance})`).join('; ') || 'no fields'} | plan=${w.plan?.headline ? 'set' : 'none'}`);
  }
}
console.log(JSON.stringify(total));

