import fs from 'node:fs';
import path from 'node:path';
const root = process.argv[2];
const byTool = {};
for (const arm of ['base', 'new'])
  for (const file of fs.readdirSync(path.join(root, arm)).filter(f => f.endsWith('.json')).sort()) {
    const r = JSON.parse(fs.readFileSync(path.join(root, arm, file), 'utf8'));
    for (const c of r.refusedCalls) {
      const key = `${arm} ${c.tool} ${c.code}`;
      (byTool[key] ??= []).push(`${file.replace('.json', '')}: ${c.arguments.slice(0, 330)}`);
    }
    if (process.argv[3] === 'guess' && file.startsWith('what-is-this'))
      console.log(`\n## ${arm} ${file} t1 reply:\n` + r.turns[1].replies.map(m => m.text).join('\n---\n').slice(0, 900));
  }
if (process.argv[3] !== 'guess')
  for (const [key, list] of Object.entries(byTool)) console.log(`\n${key} x${list.length}\n  ` + list.slice(0, 4).join('\n  '));

