TEST_CASE("every call of one response runs in order and one request answers them all", "[agent][openai][tools]")
{
    auto transport = std::make_unique<FakeTransport>();
    FakeTransport* fake = transport.get();
    OpenAIResponsesAgent agent({"key"}, std::move(transport));
    REQUIRE(agent.start(request_fixture()));
    const json output = json::array({
        {{"type", "function_call"}, {"call_id", "read-1"}, {"name", "workspace_inspect"}, {"arguments", "{}"}},
        {{"type", "function_call"}, {"call_id", "read-2"}, {"name", "printer_list"}, {"arguments", "{}"}}});
    fake->data(sse(json{{"type", "response.completed"}, {"response", {{"output", output}}}}));
    const auto first = poll_until(agent, AgentEventKind::ToolCall);
    REQUIRE(first);
    CHECK(first->tool->call_id == "read-1");
    // The second call waits for the first one's result, and nothing is sent yet.
    CHECK_FALSE(poll_until(agent, AgentEventKind::ToolCall));
    AgentToolResult pictured{"read-1", "succeeded", R"({"state":"succeeded"})"};
    pictured.image = std::make_shared<ToolImage>(ToolImage{"image/png", "iVBORw0KGgo=", 2, 1});
    REQUIRE(agent.continue_after_tool(pictured));
    CHECK(fake->requests.size() == 1);
    const auto second = poll_until(agent, AgentEventKind::ToolCall);
    REQUIRE(second);
    CHECK(second->tool->call_id == "read-2");
    REQUIRE(agent.continue_after_tool({"read-2", "succeeded", R"({"state":"succeeded","result":{"printers":[]}})"}));
    REQUIRE(fake->requests.size() == 2);
    const json input = json::parse(fake->requests.back().body)["input"];
    REQUIRE(input.size() >= 3);
    CHECK(input[input.size() - 3]["call_id"] == "read-1");
    CHECK(input[input.size() - 2]["call_id"] == "read-2");
    // A picture follows the outputs, so no output is separated from its call.
    CHECK(input.back()["role"] == "user");
}

TEST_CASE("after a failed call, a later call of the same response that changes the project is not run", "[agent][openai][tools]")
{
    auto transport = std::make_unique<FakeTransport>();
    FakeTransport* fake = transport.get();
    OpenAIResponsesAgent agent({"key"}, std::move(transport));
    REQUIRE(agent.start(request_fixture()));
    const std::string layout = json{{"objects", json::array({json{{"objectId", "72"}, {"quantity", 2}}})}}.dump();
    const json output = json::array({
        {{"type", "function_call"}, {"call_id", "change-1"}, {"name", "plate_layout"}, {"arguments", layout}},
        {{"type", "function_call"}, {"call_id", "change-2"}, {"name", "plate_layout"}, {"arguments", layout}},
        {{"type", "function_call"}, {"call_id", "read-3"}, {"name", "workspace_inspect"}, {"arguments", "{}"}}});
    fake->data(sse(json{{"type", "response.completed"}, {"response", {{"output", output}}}}));
    const auto first = poll_until(agent, AgentEventKind::ToolCall);
    REQUIRE(first);
    CHECK(first->tool->call_id == "change-1");
    REQUIRE(agent.continue_after_tool({"change-1", "failed", R"({"state":"failed","error":{"code":"stale_workspace"}})"}));
    // The model made change-2 before it could see change-1 fail. A read is harmless and still runs.
    const auto next = poll_until(agent, AgentEventKind::ToolCall);
    REQUIRE(next);
    CHECK(next->tool->call_id == "read-3");
    REQUIRE(agent.continue_after_tool({"read-3", "succeeded", R"({"state":"succeeded"})"}));
    REQUIRE(fake->requests.size() == 2);
    json answers = json::object();
    for (const json& item : json::parse(fake->requests.back().body)["input"])
        if (item.value("type", "") == "function_call_output")
            answers[item["call_id"].get<std::string>()] = json::parse(item["output"].get<std::string>());
    REQUIRE(answers.size() == 3);
    CHECK(answers["change-1"]["error"]["code"] == "stale_workspace");
    CHECK(answers["change-2"]["error"]["code"] == "not_run");
    CHECK(answers["read-3"]["state"] == "succeeded");
}

TEST_CASE("a refused call to a deferred tool is told where its parameters are", "[agent][openai][tools]")
{
    // plate_layout is deferred when tools are searched for and loaded when they are not.
    const bool deferred = GENERATE(false, true);
    CAPTURE(deferred);
    auto transport = std::make_unique<FakeTransport>();
    FakeTransport* fake = transport.get();
    OpenAIResponsesAgent agent(deferred ? namespaced_config() : OpenAIResponsesConfig{"key"}, std::move(transport));
    REQUIRE(agent.start(request_fixture()));
    const json output = json::array({
        {{"type", "function_call"}, {"call_id", "guess-1"}, {"name", "plate_layout"}, {"arguments", json{{"objectId", 72}}.dump()}},
        {{"type", "function_call"}, {"call_id", "guess-2"}, {"name", "support_enable"}, {"arguments", "{}"}}});
    fake->data(sse(json{{"type", "response.completed"}, {"response", {{"output", output}}}}));
    CHECK_FALSE(poll_until(agent, AgentEventKind::ToolCall));
    REQUIRE(fake->requests.size() == 2);
    const json input = json::parse(fake->requests.back().body)["input"];
    const auto message = [&input](std::size_t from_end) {
        return json::parse(input[input.size() - from_end]["output"].get<std::string>())["error"]["message"].get<std::string>();
    };
    // The model cannot check arguments against parameters it was never shown.
    CHECK((message(2).find("tool search") != std::string::npos) == deferred);
    CHECK((message(2).find("Check the arguments against this tool's parameters") != std::string::npos) == !deferred);
    CHECK((message(1).find("tool search") != std::string::npos) == deferred);
}

