// Moves runs that the model provider interrupted into <arm>\provider-errors\, so run.ps1 runs them again.
// A provider failure is not a result about the assistant. node set-aside.mjs <arm dir> [...]
import fs from 'node:fs';
import path from 'node:path';
const provider = new Set(['agent_service_error', 'service_unavailable', 'network_error', 'timeout', 'rate_limited', 'incomplete_response']);
for (const dir of process.argv.slice(2)) {
  const aside = path.join(dir, 'provider-errors');
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json'))) {
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    const errors = r.turns.flatMap(t => t.replies).map(m => m.error).filter(e => provider.has(e));
    if (!errors.length) continue;
    fs.mkdirSync(aside, { recursive: true });
    const stamp = Date.now();
    for (const ext of ['.json', '.log'])
      fs.renameSync(path.join(dir, file.replace('.json', ext)), path.join(aside, file.replace('.json', `-${stamp}${ext}`)));
    console.log(`${path.basename(dir)} ${file.replace('.json', '')}: set aside (${[...new Set(errors)].join(', ')})`);
  }
}

