        continue;
    const std::string call_id = item.value("call_id", "");
    ToolRequest request{item.value("name", ""), item.value("arguments", "{}")};
    const ToolDefinition* definition = ToolRegistry::instance().find(request.tool);
    const bool available = !m_title_request && definition != nullptr && available_in_app(*definition, m_allow_import, m_session.tool_names);
    ToolValidationResult validation;
    if (available)
        validation = ToolRegistry::instance().validate_call(*definition, request.arguments_json);
    // A call to no tool of this turn, or with arguments that miss the
    // tool's contract, never reaches a card. The model gets the refusal as
    // that call's result and may correct it, a bounded number of times
    // per turn.
    constexpr unsigned kRejectedCallLimit = 2;
    const bool refused = !available || !validation.valid();
    if (refused && m_config.refusal_listener)
        m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
    if (call_id.empty() || (refused && (m_title_request || m_rejected_calls >= kRejectedCallLimit))) {
        fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool call.", false});
        return;
    }
    ResponseCall next;
    if (refused) {
        ++m_rejected_calls;
        // A deferred tool's parameters reach the model only when tool
        // search returns the tool, so that is where to send it for them.
        const bool searchable = m_session.tool_names.empty() && m_config.tool_search != ToolSearch::None;
        const bool hidden     = searchable && definition != nullptr && deferred_toolset(definition->handler) != nullptr;
        json error = available ?
            json{{"code", validation.error->code},
                 {"message", validation.error->message +
                                 (hidden ? " Nothing was queued. This tool's parameters arrive when tool search returns it: "
                                           "search for it by name, then call it again with those parameters." :
                                           " Nothing was queued. Check the arguments against this tool's parameters and call it again.")}} :
            json{{"code", "unknown_tool"},
                 {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was queued. " +
                                 (searchable ? "Use one of the listed tools, or find the right one with tool search." :
                                               "Use one of the listed tools.")}};
        next.call.call_id = call_id;
        next.refusal      = json{{"state", "failed"}, {"error", std::move(error)}};
    } else {
        request.arguments_json = std::move(validation.arguments_json);
        next.changes_project   = definition->action_class != ActionClass::ReadOnly;
        next.call              = AgentToolCall{call_id, std::move(request), true};
    }
    m_calls.push_back(std::move(next));
}
if (m_calls.empty()) {
    m_busy = false;
    m_events.push_back(AgentEvent::completed());
    return;

