const fs = require('fs');
const f = 'tests/project_journey/README.md';
let s = fs.readFileSync(f, 'utf8');
const start = s.indexOf("Tools are deferred with OpenRouter's hosted");
const end = s.indexOf('## Running one');
if (start < 0 || end < 0) throw new Error('section not found');
s = s.slice(0, start) +
`Every tool is sent loaded, as the app sends them. The results sections up to
"With the deferral commit reversed" ran while the app deferred most tools
behind OpenRouter's hosted
[tool search](https://openrouter.ai/docs/guides/features/server-tools/tool-search)
(\`491b56d26b\`, since reverted); that is the setup those numbers describe.

DeepSeek V4 Flash reads text only, and OpenRouter refuses a request that holds
a picture. When the model asks for one with \`view_render\`, the harness
withholds the picture and tells the model so, and the conversation goes on.
Whether the assistant makes good use of what a picture shows needs a model
that can see one.

` + s.slice(end);
s = s.replace("- The app's built-in OpenAI route, whose tools are deferred by namespace.\n", "- The app's built-in OpenAI route.\n- What the assistant makes of a picture: the model cannot see one.\n");
fs.writeFileSync(f, s);
EOF
grep -n "journey-experiment\|toolDescriptions\|\"loaded\"" tests/project_journey/README.md | cut -c1-160

